import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        long inputNumber = Long.parseLong(reader.readLine());
        System.out.println(computeNumberOfOnes(inputNumber));
    }

    private static int getNumberOfDigits(long n) {
        return (int) Math.log10(n) + 1;
    }

    private static long createSequenceOfOnes(int length) {
        long sequence = 1;
        for (int i = 1; i < length; i++) {
            sequence = sequence * 10 + 1;
        }
        return sequence;
    }

    private static long computeNumberOfOnes(long n) {
        if (n <= 6) return n;
        int digitsCount = getNumberOfDigits(n);
        long baseSequence = createSequenceOfOnes(digitsCount);
        long totalSum = baseSequence;
        int count = 0;
        long remaining = n;

        while (totalSum < n) {
            count++;
            remaining = n - totalSum;
            totalSum += createSequenceOfOnes(digitsCount);
        }

        long result;
        if (count > 0)
            result = Math.min(count * digitsCount + computeNumberOfOnes(remaining),
                              (count + 1) * digitsCount + computeNumberOfOnes(totalSum - n));
        else
            result = (count + 1) * digitsCount + computeNumberOfOnes(totalSum - n);

        long nextSeq = createSequenceOfOnes(digitsCount + 1);
        if (nextSeq - n < n)
            result = Math.min(result, digitsCount + 1 + computeNumberOfOnes(nextSeq - n));
        return result;
    }
}
